//! `marcasite-mcp`: an MCP (Model Context Protocol) server that serves the documentation of
//! [marcasite](https://crates.io/crates/marcasite), an unofficial Rust SDK for the Polymarket
//! Predictions APIs, to coding agents.
//!
//! It speaks MCP over stdio and only serves docs: it never calls Polymarket and makes no network
//! requests. The docs are embedded at build time (`data/index.json`, generated by
//! `just docs-md`), so each release serves the marcasite release of the same version.
//!
//! Register it with an MCP client, e.g. Claude Code:
//!
//! ```sh
//! cargo install marcasite-mcp
//! claude mcp add marcasite -- marcasite-mcp
//! ```
//!
//! Stdout carries the protocol, so the server never prints to it; logs go to stderr.

mod docs;
mod index;
mod server;

use std::process::ExitCode;
use std::sync::Arc;

use rmcp::ServiceExt as _;

use crate::docs::Docs;
use crate::index::Index;
use crate::server::DocsServer;

const USAGE: &str = "\
marcasite-mcp: MCP server (stdio) serving the marcasite SDK docs to coding agents.

Usage: marcasite-mcp [--help | --version]

Run it from an MCP client, e.g. `claude mcp add marcasite -- marcasite-mcp`.";

#[tokio::main(flavor = "current_thread")]
async fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        None => {}
        Some("--help" | "-h") => return info(USAGE),
        Some("--version" | "-V") => {
            return info(&format!("marcasite-mcp {}", env!("CARGO_PKG_VERSION")));
        }
        Some(other) => {
            eprint_usage(other);
            return ExitCode::FAILURE;
        }
    }

    tracing_subscriber::fmt()
        .with_writer(std::io::stderr)
        .with_max_level(tracing::Level::INFO)
        .init();
    match run().await {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            tracing::error!("{e}");
            ExitCode::FAILURE
        }
    }
}

async fn run() -> Result<(), Box<dyn std::error::Error>> {
    let docs = Docs::new(Index::embedded()?);
    tracing::info!(
        "serving marcasite {} docs ({} items) over stdio",
        docs.version(),
        docs.item_count()
    );
    let service = DocsServer::new(Arc::new(docs))
        .serve(rmcp::transport::stdio())
        .await?;
    service.waiting().await?;
    Ok(())
}

/// Prints `--help`/`--version` output. The protocol has not started, so stdout is free.
#[allow(clippy::print_stdout)]
fn info(text: &str) -> ExitCode {
    println!("{text}");
    ExitCode::SUCCESS
}

#[allow(clippy::print_stderr)]
fn eprint_usage(arg: &str) {
    eprintln!("unknown argument `{arg}`\n\n{USAGE}");
}

